import {all, any, bool, forall, nat, record, rule} from 'gdp-wired'

export const meterRule = rule("Meter")
  .state({n: 0})
  .maps({repo_: record({has: bool, value: nat}).from({has: false, value: 0})})
  .step(({}) => ({}))

// What every state of the code is: a law about every state is about the code's with these beside it.
export const meterInvariants = [meterRule.law("n within its type's range", ({n}) => n.atMost(2147483647)), meterRule.law("repo_: a key it doesn't hold holds the defaults", ({repo_}) => forall(k => any(repo_.at(k).has, all(repo_.at(k).value.eq(0)))))]
